    if n <= 1
        isPrime = false;
        return;
    end
    if n <= 3
        isPrime = true;
        return;
    end
    if mod(n, 2) == 0
        isPrime = false;
        return;
    end

    % Write n-1 as d * 2^s
    d = n - 1;
    s = 0;
    while mod(d, 2) == 0
        d = d / 2;
        s = s + 1;
    end

    % Perform rounds of testing
    isPrime = true;
    for i = 1:rounds
        a = uint64(randi([2, double(n) - 2], 1, 1));
        x = mod_pow(a, d, n);
        if x == 1 || x == n - 1
            continue;
        end
        for j = 1:s-1
            x = mod_pow(x, 2, n);
            if x == n - 1
                break;
            end
        end
        if x ~= n - 1
            isPrime = false;
            return;
        end
    end
