        [g, x1, y1] = extended_gcd(b, mod(a, b));
        x = y1;
        y = x1 - floor(a / b) * y1;
        gcd_val = g;
    end
end

% Modular inverse (returns x such that (a * x) mod m == 1)
function inv = mod_inverse(a, m)
    [g, x, ~] = extended_gcd(a, m);
    if g ~= 1
        error('Inverse does not exist (a and m must be coprime)');
    else
        inv = mod(x, m);
    end
end

% Step 5: Generate a cryptographically strong prime
