    e = uint64(65537);  % Common public exponent

    % Generate two distinct primes p and q
    p = generate_large_prime(keySize / 2);
    q = generate_large_prime(keySize / 2);
    while isequal(p, q)
        q = generate_large_prime(keySize / 2);
    end

    n = p * q;
    phi = (p - 1) * (q - 1);

