    slip = arrayfun(@(i) calculate_slip(v_vehicle(i), v_wheel(i)), 1:length(t));
    mu = arrayfun(@(s) tire_model(s), slip);
    torque = arrayfun(@(ti) braking_torque(ti, t_start_brake, slope_brake, torque_max_brake), t);

    % Plot Results
    figure;
    subplot(2,2,1);
    plot(t, v_vehicle, 'b', t, v_wheel, 'r');
    title('Speeds (m/s)');
    xlabel('Time (s)');
    legend('Vehicle', 'Wheel');

    subplot(2,2,2);
    plot(t, slip, 'g');
    title('Slip Ratio');
    xlabel('Time (s)');

    subplot(2,2,3);
    plot(t, mu, 'm');
    title('Friction Coefficient');
    xlabel('Time (s)');

    subplot(2,2,4);
    plot(t, torque, 'k');
    title('Braking Torque (Nm)');
    xlabel('Time (s)');
    sgtitle('ABS Simulation with Ramp Braking Torque');

    % === Enhanced Features ===
    % 1. User Input for Parameter Tuning
    params = get_user_parameters();

    % 2. Advanced Visualization
    animate_results(t, v_vehicle, v_wheel, slip, mu, torque);

    % 3. Toolbox Integration Suggestions
    toolbox_integration_suggestions();
end

% Braking Torque Function with Ramp Profile
function torque = braking_torque(t, t_start, slope, torque_max)
    % Calculate braking torque as a ramp function with saturation
    % Inputs:
    %   t - Current time
    %   t_start - Time to start braking
    %   slope - Ramp slope (Nm/s)
    %   torque_max - Maximum torque (Nm)
    if nargin <2, t_start = 2; end
    if nargin <3, slope = 100; end
    if nargin <4, torque_max = 2000; end

    if t >= t_start
        % Use ramp signal after t_start
        torque = ramp_signal(t - t_start, slope);
        % Limit to maximum torque
        torque = min(torque, torque_max);
    else
        torque = 0;
    end
end

% Ramp Signal Function
function signal = ramp_signal(t, slope)
    % Generate a linearly increasing ramp signal
    % Inputs:
    %   t - Time vector or scalar
    %   slope - Rate of increase
    if nargin <2, slope = 100; end
    signal = slope * t;
end

% Tire Model (Simplified Magic Formula)
function mu = tire_model(slip, mu_max, s_max)
    % Calculate friction coefficient using simplified magic formula
    % Inputs:
    %   slip - Slip ratio
    %   mu_max - Peak friction coefficient
    %   s_max - Slip at peak friction
    if nargin <2, mu_max = 0.9; end
    if nargin <3, s_max = 0.2; end

    if slip > 0
        mu = mu_max * (1 - exp(-s_max/slip));  % Nonlinear friction
    else
        mu = 0;
    end
end

% Slip Calculation
function slip = calculate_slip(v_vehicle, v_wheel)
    % Calculate slip ratio from vehicle and wheel speeds
    % Inputs:
    %   v_vehicle - Vehicle speed
    %   v_wheel - Wheel speed
    if v_vehicle <= 0
        slip = 0;
    else
        slip = (v_vehicle - v_wheel) / v_vehicle;  % Slip definition
    end
end

% ABS Control Logic
function mod = abs_cycle(slip, threshold)
    % Simple threshold-based ABS controller
    % Inputs:
    %   slip - Current slip ratio
    %   threshold - Optimal slip threshold
    if nargin <2, threshold = 0.15; end
    mod = 0.5 * (slip > threshold) + 1.0 * (slip <= threshold);  % Torque modulation
end

% Wheel Dynamics Model
function dydt = wheel_dynamics(t, y, m, R, I, Fz, t_start_brake, slope_brake, torque_max_brake)
    % System of differential equations for wheel dynamics
    % Inputs:
    %   t - Time
    %   y - State vector [v_vehicle, v_wheel, omega]
    %   m - Vehicle mass
    %   R - Tire radius
    %   I - Wheel inertia
    %   Fz - Vertical load
    %   t_start_brake - Braking start time
    %   slope_brake - Torque ramp slope
    %   torque_max_brake - Maximum torque

    v_vehicle = y(1);
    v_wheel = y(2);
    omega = y(3);

    % Calculate slip
    slip = calculate_slip(v_vehicle, v_wheel);

    % Tire force
    mu = tire_model(slip);
    Fx = mu * Fz;  % Longitudinal force

    % Braking torque with ABS modulation
    T_brake = braking_torque(t, t_start_brake, slope_brake, torque_max_brake) * abs_cycle(slip);

    % Equations of motion
    dv_vehicle = -Fx / m;  % Vehicle deceleration
    domega = (Fx * R - T_brake) / I;  % Wheel angular acceleration

    dydt = [dv_vehicle; dv_vehicle; domega];  % State derivatives
end

% User Input for Parameter Tuning
function params = get_user_parameters()
    % Interactive parameter input with defaults
    fprintf('Enter simulation parameters (press Enter for default values):\n');
    params.m = str2double(input('Vehicle mass (kg) [1200]: ', 's'));
    if isempty(params.m), params.m = 1200; end

    params.I = str2double(input('Wheel inertia (kg.m^2) [1.5]: ', 's'));
    if isempty(params.I), params.I = 1.5; end

    params.R = str2double(input('Tire radius (m) [0.3]: ', 's'));
    if isempty(params.R), params.R = 0.3; end

    params.t_start = str2double(input('Brake start time (s) [2]: ', 's'));
    if isempty(params.t_start), params.t_start = 2; end

    params.slope = str2double(input('Torque ramp slope (Nm/s) [1000]: ', 's'));
    if isempty(params.slope), params.slope = 1000; end

    params.torque_max = str2double(input('Max torque (Nm) [2000]: ', 's'));
    if isempty(params.torque_max), params.torque_max = 2000; end

    params.threshold = str2double(input('ABS threshold [0.15]: ', 's'));
    if isempty(params.threshold), params.threshold = 0.15; end
end

% Animated Visualization
function animate_results(t, v_vehicle, v_wheel, slip, mu, torque)
    % Create animated visualization of results
    fig = figure;
    ax1 = subplot(2,2,1);
    ax2 = subplot(2,2,2);
    ax3 = subplot(2,2,3);
    ax4 = subplot(2,2,4);

    % Initialize lines
    h1 = animatedline(ax1, 'Color', 'b');
    h2 = animatedline(ax1, 'Color', 'r');
    h3 = animatedline(ax2, 'Color', 'g');
    h4 = animatedline(ax3, 'Color', 'm');
    h5 = animatedline(ax4, 'Color', 'k');

    % Set labels and limits
    title(ax1, 'Speeds (m/s)');
    xlabel(ax1, 'Time (s)');
    xlim(ax1, [0 t(end)]);
    ylim(ax1, [0 max([v_vehicle; v_wheel]) * 1.1]);
    legend(ax1, {'Vehicle', 'Wheel'});

    title(ax2, 'Slip Ratio');
    xlabel(ax2, 'Time (s)');
    xlim(ax2, [0 t(end)]);
    ylim(ax2, [0 max(slip) * 1.1]);

    title(ax3, 'Friction Coefficient');
    xlabel(ax3, 'Time (s)');
    xlim(ax3, [0 t(end)]);
    ylim(ax3, [0 max(mu) * 1.1]);

    title(ax4, 'Braking Torque (Nm)');
    xlabel(ax4, 'Time (s)');
    xlim(ax4, [0 t(end)]);
    ylim(ax4, [0 max(torque) * 1.1]);

    title(fig, 'ABS Simulation Results - Animated');

    % Animate
    for i = 1:length(t)
        addpoints(h1, t(i), v_vehicle(i));
        addpoints(h2, t(i), v_wheel(i));
        addpoints(h3, t(i), slip(i));
        addpoints(h4, t(i), mu(i));
        addpoints(h5, t(i), torque(i));
        drawnow limitrate;
        if ~ishandle(fig)
            break;
        end
    end
end

